\"\"\"Minimal OpenAI Responses API client using only the Python standard library.

Sends text prompts to OpenAI's Responses API
(https://platform.openai.com/docs/api-reference/responses) without any
third-party dependencies.

The API key is read from the "'``OPENAI_API_KEY`` environment variable and is
never written to disk, logged, or included in error messages.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Iterable, Iterator, Mapping, Optional

__all__ = [
    "DEFAULT_BASE_URL",
    "DEFAULT_MODEL",
    "OpenAIClient",
    "OpenAIError",
    "send_prompt",
]

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4o-mini"
_API_KEY_ENV = "OPENAI_API_KEY"


class OpenAIError(Exception):
    """Raised when the OpenAI API returns an error or is misconfigured."""

    def __init__(self, message: str, status: Optional[int] = None) -> None:
        super().__init__(message)
        self.status = status


class OpenAIClient:
    """A tiny, dependency-free client for the OpenAI Responses API.

    Args:
        api_key: Bearer token. Defaults to the ``OPENAI_API_KEY`` env var.
        base_url: API base URL. Defaults to ``https://api.openai.com/v1``.
        model: Default model used when a call does not specify one.
        timeout: Per-request timeout in seconds.
    """

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        base_url: str = DEFAULT_BASE_URL,
        model: str = DEFAULT_MODEL,
        timeout: float = 60.0,
    ) -> None:
        resolved_key = api_key if api_key is not None else os.environ.get(_API_KEY_ENV)
        if not resolved_key:
            raise OpenAIError(
                "No API key provided. Set the "
                f"{_API_KEY_ENV} environment variable or pass api_key=..."
            )
        self._api_key = resolved_key
        self._base_url = base_url.rstrip("/")
        self._model = model
        self._timeout = timeout

    def create_response(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        extra: Optional[Mapping[str, Any]] = None,
    ) -> dict:
        """Call the Responses API and return the parsed JSON response.

        ``prompt`` is sent as the ``input`` and is treated as private: it is
        never logged by this module.
        """
        if not isinstance(prompt, str) or not prompt:
            raise ValueError("prompt must be a non-empty string")

        payload: dict[str, Any] = {
            "model": model or self._model,
            "input": prompt,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if temperature is not None:
            payload["temperature"] = temperature
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        if extra:
            payload.update(extra)

        return self._post("/responses", payload)

    def send_prompt(self, prompt: str, **kwargs: Any) -> str:
        """Send ``prompt`` and return the concatenated output text."""
        return extract_text(self.create_response(prompt, **kwargs))

    def stream_response(self, prompt: str, **kwargs: Any) -> Iterator[dict]:
        """Yield server-sent events from a streaming Responses API call.

        Each yielded item is the parsed JSON object of an SSE ``data:`` line.
        """
        payload: dict[str, Any] = {"model": kwargs.pop("model", None) or self._model,
                                   "input": prompt, "stream": True}
        payload.update(kwargs.pop("extra", None) or {})
        for key in ("instructions", "temperature", "max_output_tokens"):
            value = kwargs.pop(key, None)
            if value is not None:
                payload[key] = value
        if kwargs:
            raise TypeError(f"unexpected keyword arguments: {sorted(kwargs)}")

        request = self._build_request("/responses", payload)
        try:
            with urllib.request.urlopen(request, timeout=self._timeout) as response:
                for raw_line in response:
                    line = raw_line.decode("utf-8").strip()
                    if line.startswith("data:"):
                        data = line[len("data:"):].strip()
                        if data and data != "[DONE]":
                            yield json.loads(data)
        except urllib.error.HTTPError as exc:
            raise self._http_error(exc) from None

    # -- internals ---------------------------------------------------------

    def _build_request(self, path: str, payload: dict) -> urllib.request.Request:
        body = json.dumps(payload).encode("utf-8")
        return urllib.request.Request(
            url=f"{self._base_url}{path}",
            data=body,
            method="POST",
            headers={
                "Authorization": f"Bearer {self._api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
        )

    def _post(self, path: str, payload: dict) -> dict:
        request = self._build_request(path, payload)
        try:
            with urllib.request.urlopen(request, timeout=self._timeout) as response:
                charset = response.headers.get_content_charset() or "utf-8"
                raw = response.read().decode(charset)
        except urllib.error.HTTPError as exc:
            raise self._http_error(exc) from None
        except urllib.error.URLError as exc:
            raise OpenAIError(f"Network error contacting OpenAI: {exc.reason}") from None

        if not raw:
            return {}
        try:
            return json.loads(raw)
        except json.JSONDecodeError as exc:
            raise OpenAIError(f"Invalid JSON in API response: {exc}") from None

    @staticmethod
    def _http_error(exc: urllib.error.HTTPError) -> OpenAIError:
        try:
            payload = json.loads(exc.read().decode("utf-8"))
            message = payload.get("error", {}).get("message") or payload.get("message")
        except Exception:
            message = None
        if not message:
            message = f"HTTP {exc.code} {exc.reason}"
        return OpenAIError(message, status=exc.code)


def extract_text(response: Mapping[str, Any]) -> str:
    """Pull plain text out of a Responses API JSON payload.

    Handles the documented ``output`` structure as well as the SDK'"'s
    top-level "'``output_text`` convenience field.
    """
    text = response.get("output_text")
    if isinstance(text, str) and text:
        return text

    chunks: list[str] = []
    for item in response.get("output", []) or []:
        if not isinstance(item, Mapping):
            continue
        for part in item.get("content", []) or []:
            if not isinstance(part, Mapping):
                continue
            value = part.get("text")
            if isinstance(value, str):
                chunks.append(value)
    return "".join(chunks)


def send_prompt(
    prompt: str,
    *,
    api_key: [REDACTED_SECRET] = None,
    model: str = DEFAULT_MODEL,
    instructions: Optional[str] = None,
    base_url: str = DEFAULT_BASE_URL,
    timeout: float = 60.0,
) -> str:
    """One-shot helper: send ``prompt`` and return the response text.

    Example::

        from openai_client import send_prompt

        print(send_prompt("Say hello in five words."))
    """
    client = OpenAIClient(api_key=[REDACTED_SECRET] base_url=base_url, model=model, timeout=timeout)
    return client.send_prompt(prompt, instructions=instructions)


def _read_prompt(args_prompt: Iterable[str]) -> str:
    words = list(args_prompt)
    if words:
        return " ".join(words)
    if not sys.stdin.isatty():
        return sys.stdin.read().strip()
    raise OpenAIError("No prompt provided. Pass text as arguments or via stdin.")


def main(argv: Optional[list[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        description="Send a text prompt to OpenAI'"'s Responses API.\"
    )
    parser.add_argument(\"prompt\", nargs=\"*\", help=\"Prompt text (or pipe via stdin).\")
    parser.add_argument(\"--model\", default=DEFAULT_MODEL, help=\"Model name.\")
    parser.add_argument(\"--instructions\", help=\"Optional system instructions.\")
    parser.add_argument(\"--max-output-tokens\", type=int, default=None)
    parser.add_argument(\"--temperature\", type=float, default=None)
    parser.add_argument(\"--base-url\", default=DEFAULT_BASE_URL)
    parser.add_argument(\"--timeout\", type=float, default=60.0)
    args = parser.parse_args(argv)

    try:
        prompt = _read_prompt(args.prompt)
        client = OpenAIClient(model=args.model, base_url=args.base_url, timeout=args.timeout)
        output = client.send_prompt(
            prompt,
            instructions=args.instructions,
            temperature=args.temperature,
            max_output_tokens=args.max_output_tokens,
        )
    except OpenAIError as exc:
        print(f\"error: {exc}\", file=sys.stderr)
        return 1

    print(output)
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
